    for i,j,v in px: g[i-rr0][j-cc0]=v
    out=[[frame]*(c1-c0+1) for _ in range(r1-r0+1)]
    for bi in range(bh):
        for bj in range(bw):
            for a in range(sh):
                for b2 in range(sw):
                    oi=r0+1+bi*sh+a; oj=c0+1+bj*sw+b2
                    if 0<=oi<len(out) and 0<=oj<len(out[0]):
                        out[oi][oj]=g[bi][bj]
    return out
