def f(inp, dbg=False):
    H,W=len(inp),len(inp[0])
    from collections import Counter
    cnt=Counter(x for row in inp for x in row if x!=0)
    frame=None; rr=None
    for c,n in cnt.most_common():
        cells=[(i,j) for i in range(H) for j in range(W) if inp[i][j]==c]
        rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        perim={(i,c0) for i in range(r0,r1+1)}|{(i,c1) for i in range(r0,r1+1)}|{(r0,j) for j in range(c0,c1+1)}|{(r1,j) for j in range(c0,c1+1)}
        if len(cells)>=8 and set(cells)==perim:
            frame=c; rr=(r0,r1,c0,c1); break
    ih,iw=rr[1]-rr[0]-1,rr[3]-rr[2]-1
    px=[(i,j,inp[i][j]) for i in range(H) for j in range(W)
        if inp[i][j]!=0 and inp[i][j]!=frame and not(rr[0]<=i<=rr[1] and rr[2]<=j<=rr[3])]
    ri=[p[0] for p in px]; ci=[p[1] for p in px]
    rr0,rr1,cc0,cc1=min(ri),max(ri),min(ci),max(ci)
    bh,bw=rr1-rr0+1,cc1-cc0+1
    s=min(ih//bh, iw//bw) if bh and bw else 1
    g=[[inp[i][j] for j in range(cc0,cc1+1)] for i in range(rr0,rr1+1)]
    th,tw=s*bh,s*bw
    print(dbg,'frame',frame,rr,'interior',ih,iw,'pattern',(bh,bw),'s',s,'target',th,tw,'out',(th+2,tw+2))
    if th>ih or tw>iw: print(' MISMATCH'); 
    out=[[frame]*(tw+2) for _ in range(th+2)]
    for bi in range(bh):
        for bj in range(bw):
            v=g[bi][bj]
            if v!=0:
                for a in range(s):
                    for b2 in range(s):
                        oi=rr[0]+1+bi*s+a; oj=rr[2]+1+bj*s+b2
                        if 0<=oi<len(out) and 0<=oj<len(out[0]):
                            out[oi][oj]=v
    return out
